select pg_catalog.pg_switch_wal() as c0, pg_catalog.numeric( cast( pg_catalog.bit_and( cast((select score from public.users limit 1 offset 4) as int2)) over (partition by subq_0.c4 order by subq_0.c4,subq_0.c3) as int2)) as c1, pg_catalog.txid_current_if_assigned() as c2, subq_0.c0 as c3, subq_0.c0 as c4, subq_0.c5 as c5, pg_catalog.pg_terminate_backend( cast(pg_catalog.inet_server_port() as int4), cast(subq_0.c6 as int8)) as c6, subq_0.c6 as c7, subq_0.c2 as c8 from (select pg_catalog.quote_ident( cast((select bio from public.users limit 1 offset 5) as text)) as c0, sample_0.log_time as c1, (select occurred_at from public.events_by_type limit 1 offset 3) as c2, sample_0.sensor_id as c3, pg_catalog.get_current_ts_config() as c4, sample_0.reading as c5, pg_catalog.lastval() as c6 from public.measurements_2024_q2 as sample_0 tablesample system (6.6) where sample_0.reading is not NULL limit 101) as subq_0 where cast(coalesce((select search_vec from public.products limit 1 offset 5) , case when case when (select duration from public.events limit 1 offset 3) >= (select duration from public.events limit 1 offset 2) then cast(null as timetz) else cast(null as timetz) end = cast(null as timetz) then (select search_vec from public.products limit 1 offset 6) else (select search_vec from public.products limit 1 offset 6) end ) as tsvector) > (select search_vec from public.products limit 1 offset 23) limit 140;
